@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/*
  Visual system: Vercel editorial / product chrome.
  Cool neutrals, hairline borders, Geist, blue activity — not GitHub green,
  not generic slate portfolio gray.
*/
@theme {
  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;

  --color-background: #ffffff;
  --color-background-muted: #fafafa;
  --color-foreground: #171717;
  --color-muted: #666666;
  --color-faint: #999999;
  --color-border: #ebebeb;
  --color-border-strong: #dddddd;
  --color-surface: #ffffff;
  --color-surface-hover: #fafafa;
  --color-accent: #0070f3;
  --color-accent-muted: #3291ff;
  --color-link: #171717;

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-out-quad: cubic-bezier(0.25, 1, 0.5, 1);
}

.dark {
  --color-background: #000000;
  --color-background-muted: #0a0a0a;
  --color-foreground: #ededed;
  --color-muted: #888888;
  --color-faint: #666666;
  --color-border: #333333;
  --color-border-strong: #444444;
  --color-surface: #0a0a0a;
  --color-surface-hover: #111111;
  --color-accent: #3291ff;
  --color-accent-muted: #0070f3;
  --color-link: #ededed;
}

@layer base {
  html {
    color-scheme: light;
    scroll-behavior: smooth;
  }

  html.dark {
    color-scheme: dark;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-feature-settings: "ss01" 1, "cv01" 1, "liga" 1, "calt" 1;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    background: color-mix(in srgb, var(--color-accent) 22%, transparent);
  }

  a {
    @apply text-link;
  }

  :focus-visible {
    outline: 2px solid var(--color-foreground);
    outline-offset: 3px;
  }
}

/* Atmosphere — soft field, not flat white void */
.site-atmosphere {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  background: var(--color-background);
}

.site-atmosphere::before {
  content: "";
  position: absolute;
  inset: -20% -10% auto;
  height: 55vh;
  background:
    radial-gradient(
      60% 50% at 15% 0%,
      color-mix(in srgb, var(--color-accent) 8%, transparent),
      transparent 70%
    ),
    radial-gradient(
      50% 40% at 85% 10%,
      color-mix(in srgb, var(--color-foreground) 4%, transparent),
      transparent 65%
    );
}

.site-atmosphere::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.35;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  mix-blend-mode: multiply;
}

.dark .site-atmosphere::after {
  opacity: 0.2;
  mix-blend-mode: soft-light;
}

.skip-link {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link:focus {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 50;
  width: auto;
  height: auto;
  margin: 0;
  clip: auto;
  overflow: visible;
  white-space: normal;
  border-radius: 0.5rem;
  background-color: var(--color-foreground);
  color: var(--color-background);
  padding: 0.5rem 0.75rem;
  font-size: 0.8125rem;
  font-weight: 500;
  outline: none;
}

.container-editorial {
  @apply mx-auto w-full max-w-[42rem] px-5 sm:px-6;
}

.container-wide {
  @apply mx-auto w-full max-w-[52rem] px-5 sm:px-6;
}

/* Type */
.display-title {
  @apply text-[2rem] font-semibold tracking-[-0.04em] text-foreground text-pretty sm:text-[2.5rem] sm:leading-[1.1];
}

.section-title {
  @apply text-[0.8125rem] font-medium uppercase tracking-[0.08em] text-faint;
}

.body-copy {
  @apply text-[15px] leading-7 text-muted text-pretty;
}

.meta-copy {
  @apply font-mono text-[12px] leading-4 tracking-[-0.01em] text-faint tabular-nums;
}

/* Links */
.link-editorial {
  @apply relative inline-flex min-h-9 items-center text-foreground no-underline;
  transition: color 160ms var(--ease-out-quad);
}

.link-editorial::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0.35rem;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 220ms var(--ease-out-expo);
}

.link-editorial:hover::after,
.link-editorial:focus-visible::after {
  transform: scaleX(1);
}

.link-editorial-muted {
  @apply inline-flex min-h-9 items-center text-muted no-underline;
  transition: color 160ms var(--ease-out-quad);
}

.link-editorial-muted:hover {
  color: var(--color-foreground);
}

.section-home {
  @apply border-t border-border pt-12 pb-10 sm:pt-14 sm:pb-12;
}

/* Project / writing rows — changelog energy */
.row-interactive {
  @apply relative -mx-3 rounded-lg px-3 py-3 transition-[background-color,transform] duration-200;
  transition-timing-function: var(--ease-out-quad);
}

.row-interactive:hover {
  background: var(--color-surface-hover);
}

.row-interactive:active {
  transform: scale(0.997);
}

.row-arrow {
  @apply text-faint opacity-0 transition-[opacity,transform] duration-200;
  transition-timing-function: var(--ease-out-expo);
  transform: translateX(-4px);
}

.row-interactive:hover .row-arrow,
.row-interactive:focus-within .row-arrow {
  opacity: 1;
  transform: translateX(0);
}

/* MDX */
.prose-editorial {
  @apply text-[16px] leading-7 text-foreground;
}

.prose-editorial :where(p, ul, ol, blockquote, pre, table) {
  @apply my-5;
}

.prose-editorial :where(h2, h3, h4) {
  @apply mt-10 mb-3 font-semibold tracking-[-0.02em] text-foreground;
}

.prose-editorial h2 {
  @apply text-[1.375rem];
}

.prose-editorial h3 {
  @apply text-[1.125rem];
}

.prose-editorial :where(ul, ol) {
  @apply pl-5;
}

.prose-editorial ul {
  @apply list-disc;
}

.prose-editorial ol {
  @apply list-decimal;
}

.prose-editorial a {
  color: var(--color-accent);
  text-decoration: none;
  background-image: linear-gradient(currentColor, currentColor);
  background-position: 0 100%;
  background-repeat: no-repeat;
  background-size: 0 1px;
  transition: background-size 200ms var(--ease-out-expo);
}

.prose-editorial a:hover {
  background-size: 100% 1px;
}

.prose-editorial a.anchor {
  @apply no-underline;
  background-image: none;
}

.prose-editorial :where(code):not(pre code) {
  @apply rounded-[4px] px-1.5 py-0.5 font-mono text-[0.84em];
  background: var(--color-background-muted);
  border: 1px solid var(--color-border);
}

.prose-editorial pre {
  @apply overflow-x-auto rounded-lg border border-border p-4 font-mono text-[13px] leading-6;
  background: var(--color-background-muted);
}

.prose-editorial blockquote {
  @apply border-l-2 border-border-strong pl-4 text-muted;
}

.prose-editorial img {
  @apply my-6 h-auto w-full rounded-lg;
}

/* AI Activity — Vercel analytics blue, not GitHub green */
.activity-cell {
  border-radius: 2px;
  transition:
    transform 120ms var(--ease-out-quad),
    box-shadow 120ms var(--ease-out-quad),
    opacity 120ms var(--ease-out-quad);
}

.activity-cell:hover,
.activity-cell:focus-visible {
  transform: scale(1.35);
  z-index: 1;
  box-shadow: 0 0 0 1px var(--color-background);
}

.activity-cell.intensity-0 {
  background-color: #ebedf0;
}

.activity-cell.intensity-1 {
  background-color: #c8e1ff;
}

.activity-cell.intensity-2 {
  background-color: #79b8ff;
}

.activity-cell.intensity-3 {
  background-color: #2188ff;
}

.activity-cell.intensity-4 {
  background-color: #0070f3;
}

.dark .activity-cell.intensity-0 {
  background-color: #161b22;
  box-shadow: inset 0 0 0 1px #21262d;
}

.dark .activity-cell.intensity-1 {
  background-color: #0d419d;
}

.dark .activity-cell.intensity-2 {
  background-color: #0e64d8;
}

.dark .activity-cell.intensity-3 {
  background-color: #1f6feb;
}

.dark .activity-cell.intensity-4 {
  background-color: #58a6ff;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .link-editorial::after,
  .row-arrow,
  .activity-cell,
  .row-interactive {
    transition: none !important;
  }
}

